function easternCandidate(st2, kind, rng) {
  const pat = wpick(rng, st2.kinds[kind]);
  const r = pat(rng);
  const cs = [...r.zh];
  if (new Set(cs).size !== cs.length) return null;
  if (!toneOk(r.zh, rng)) return null;
  return { zh: r.zh, generic: r.generic, tokens: r.tokens };
}

