// src/gen/civ/development.ts
init_tableGroups();
var RESOURCES = ["\u7CAE", "\u7272\u755C", "\u94DC\u9521", "\u94C1", "\u7164", "\u6728\u6750", "\u76D0", "\u6E14\u83B7", "\u77F3\u6CB9", "\u7A00\u6709\u77FF", "\u91D1\u94F6"];
var RESOURCE_COUNT = 11;
var RESOURCE_SHARE = [0.7, 0.5, 0.22, 0.4, 0.2, 0.55, 0.3, 0.45, 0.15, 0.12, 0.12];
var DISCOVER_AT = [0, 0, 0.6, 1.5, 4.5, 0, 0, 0, 5.5, 6.5, 0.4];
var LIFE = [0, 0, 2500, 3e3, 1200, 0, 0, 0, 400, 800, 800];
var DEPLETE = [15e-4, 3e-3, 0, 0, 0, 4e-3, 0, 4e-3, 0, 0, 0];
var REGROW = 3e-3;
var AVAIL_SCALE = 80;
var CAP_COUNT = 5;
var ERAS = ["\u77F3\u5668", "\u9752\u94DC", "\u94C1\u5668", "\u4E2D\u53E4", "\u706B\u836F", "\u5DE5\u4E1A", "\u7535\u6C14", "\u4FE1\u606F", "\u672A\u6765"];
var ERA_YEARS = [1e3, 800, 700, 750, 3e3, 1600, 1300, 1500, 2e3];
var LEVEL_MAX = 9;
var LEVEL_SCALE = 28;
var BAD_LEVEL = 255;
var STEP = 20;
var SNAP = 100;
var LEARN = [15e-4, 12e-4, 25e-4, 1e-3];
var SAME_STATE = 2;
var ADMIN_ABROAD = 0.3;
var LINK = (() => {
  const t = [1, 1, 1, 1, 1];
  t[1 /* River */] = 1.1;
  t[2 /* Mountain */] = 0.35;
  t[3 /* Strait */] = 0.6;
  t[4 /* SeaRoute */] = 0.25;
  return t;
})();
var SEA_PER_TRANSPORT = 0.08;
var SEA_ROUTE = 4 /* SeaRoute */;
var OVERSHOOT = 0.8;
var OVERSHOOT_LEARN = 2;
var OVERSHOOT_SLOW = 0.25;
var GATE_NEAR = 0.3;
var GATE_SLOW = 0.15;
var RECOVER = 0.02;
var WAR_KEEP = 0.8;
var HIT_CONQUER = [0.08, 0.05, 0, 0.1];
var HIT_BATTLE = [0.04, 0.02, 0, 0];
var HIT_SACK = [0.12, 0.05, 0.08, 0.04];
var HIT_RUIN = [0.2, 0.1, 0.15, 0.08];
