// src/gen/civ/ideoTables.ts
var BIG4 = 1e15;
function ideoCards(k2, step2) {
  const [\u751F\u4EA7, \u8FD0\u8F93, \u4FE1\u606F, \u884C\u653F, \u52A8\u5458] = k2.CAPS;
  const names2 = [...k2.NAMES];
  const K3 = names2.length;
  const num8 = (id3, name, cols, off = 0) => ({ id: id3, name, unit: "region", input: true, min: -BIG4, max: BIG4, off, ...cols ? { cols: [...cols] } : {} });
  const pol = (id3, name, off) => ({ ...num8(id3, name, void 0, off), unit: "polity" });
  const id2 = (cid, name) => ({ id: cid, name, unit: "region", kind: "id", min: -1, max: 1e9, off: -1 });
  const inputs = [
    id2("\u6C11\u65CF", "\u5F52\u54EA\u4E2A\u6C11\u65CF"),
    id2("\u56FD", "\u5F52\u54EA\u56FD"),
    num8("\u80FD\u529B", "\u4E94\u79CD\u80FD\u529B(\u548C\u65F6\u4EE3\u540C\u4E00\u628A\u5C3A\u5B50)", [\u751F\u4EA7, \u8FD0\u8F93, \u4FE1\u606F, \u884C\u653F, \u52A8\u5458]),
    num8("\u57CE\u6C11", "\u57CE\u7684\u4EBA\u53E3(\u5343\u4EBA;\u6CA1\u6709\u57CE = 0)"),
    num8("\u4EBA\u6570", "\u4E00\u5DDE\u7684\u4EBA\u53E3(\u57CE\u52A0\u4E61\u6751,\u5343\u4EBA)"),
    num8("\u6E2F\u53E3", "\u6709\u6CA1\u6709\u6E2F\u53E3"),
    num8("\u7CAE", "\u7CAE\u773C\u4E0B\u80FD\u7528\u591A\u5C11(0\u20133 \u6863)"),
    num8("\u77FF", "\u94DC\u9521\u3001\u94C1\u3001\u7164\u773C\u4E0B\u80FD\u7528\u591A\u5C11(\u5404 0\u20133 \u6863,\u52A0\u8D77\u6765)"),
    pol("\u56FD\u53F7", "\u56FD\u53F7\u6863\u4F4D", -1),
    pol("\u5DDE\u6570", "\u56FD\u5BB6\u6709\u51E0\u5DDE", 0)
  ];
  const root2 = {};
  names2.forEach((n2, i) => root2[n2] = [`let \u57CE = \u57CE\u6C11 / (\u57CE\u6C11 + CITY_HALF)`, `clamp(${k2.ROOTS[i]}, 0, 1)`].join("\n"));
  const ready = (cap, lv) => `clamp((\u80FD\u529B[${cap}] - ${lv} + BELOW[col]) / (BELOW[col] + ABOVE), 0, 1)`;
  const press = Array.from({ length: K3 }, (_, j) => `RIVAL[col * ${K3} + ${j}] * \u601D\u6F6E[${j}]`).join(" + ");
  const nbLive = "has(nb.\u6C11\u65CF)";
  const link = `(LINK[edge.kind] + if(edge.kind == SEA_ROUTE, SEA_PER_TRANSPORT * \u80FD\u529B.${\u8FD0\u8F93}, 0)) * if(has(\u56FD) and nb.\u56FD == \u56FD, SAME_STATE, 1)`;
  const ideoRule = [
    "let \u5728 = has(\u6C11\u65CF)",
    // 这州能到多高:合 × 前提够不够 × 助长 × (1 − 对头压的)
    `let \u5907 = min(${ready("NEED_A_CAP[col]", "NEED_A_LV[col]")}, ${ready("NEED_B_CAP[col]", "NEED_B_LV[col]")})`,
    `let \u52A9 = 1 - BOOST + BOOST * ${ready("BOOST_CAP[col]", "BOOST_LV[col]")}`,
    `let \u538B = ${press}`,
    "let \u6807 = if(\u5728, \u5408 * \u5907 * \u52A9 * max(0, 1 - \u538B), 0)",
    // 向邻州学:向接受度最高的有人住的邻州靠拢,同一国快、跨国慢,翻山、过海峡、走航线更慢;各说快慢不一(PACE);
    // 合得来的学得多(合不来的学到 RECEPT 那几成,前提差得远的学不进来);有报刊的快。一步至多追平最高的邻州
    `let \u5DEE = nbmax(nb.\u601D\u6F6E - \u601D\u6F6E, 0, ${nbLive} and nb.\u601D\u6F6E > \u601D\u6F6E)`,
    `let \u5B66 = nbmax((nb.\u601D\u6F6E - \u601D\u6F6E) * ${link}, 0, ${nbLive} and nb.\u601D\u6F6E > \u601D\u6F6E)`,
    "let \u62A5 = if(\u80FD\u529B[PRESS_CAP] >= PRESS_LV, PRESS_UP, 1)",
    "let \u4F20 = if(\u5728, min(\u5DEE, dt * LEARN * PACE[col] * \u62A5 * (RECEPT[col] * \u5907 + (1 - RECEPT[col]) * \u6807) * \u5B66), 0)",
    // 扎根:往标长,刚传进来的(不到 FOOT)长得慢;退潮:比标高的往下掉
    "let \u957F = if(\u601D\u6F6E < \u6807, GROW * (\u6807 - \u601D\u6F6E) * min(1, \u601D\u6F6E / FOOT), 0)",
    "let \u9000 = if(\u601D\u6F6E > \u6807, FADE * (\u601D\u6F6E - \u6807), 0)",
    "if(dt == 0, \u601D\u6F6E, clamp(\u601D\u6F6E + \u4F20 + dt * (\u957F - \u9000), 0, 1))"
  ].join("\n");
  const polityRule = ["let w = sumof(\u4EBA\u6570 + 1, has(\u6C11\u65CF))", "if(w > 0, sumof(\u601D\u6F6E * (\u4EBA\u6570 + 1), has(\u6C11\u65CF)) / w, 0)"].join("\n");
  const consts = {
    NEED_A_CAP: k2.NEED_A_CAP,
    NEED_A_LV: k2.NEED_A_LV,
    NEED_B_CAP: k2.NEED_B_CAP,
    NEED_B_LV: k2.NEED_B_LV,
    BOOST_CAP: k2.BOOST_CAP,
    BOOST_LV: k2.BOOST_LV,
    RIVAL: k2.RIVAL,
    BELOW: k2.BELOW,
    ABOVE: k2.ABOVE,
    BOOST: k2.BOOST,
    LEARN: k2.LEARN,
    PACE: k2.PACE,
    SAME_STATE: k2.SAME_STATE,
    LINK: k2.LINK,
    SEA_ROUTE: k2.SEA_ROUTE,
    SEA_PER_TRANSPORT: k2.SEA_PER_TRANSPORT,
    RECEPT: k2.RECEPT,
    PRESS_CAP: k2.PRESS_CAP,
    PRESS_LV: k2.PRESS_LV,
    PRESS_UP: k2.PRESS_UP,
    GROW: k2.GROW,
    FOOT: k2.FOOT,
    FADE: k2.FADE,
    CITY_HALF: k2.CITY_HALF
  };
  const tables2 = [
    { id: "\u5408", name: "\u5404\u8BF4\u5728\u8FD9\u5DDE\u5408\u4E0D\u5408(0\u20131)", unit: "region", every: step2, cols: names2, min: 0, max: 1, off: 0, rule: root2 },
    // 自己是 0、邻州也全是 0 的格子一定还是 0(没传进来就没有;冒出来由事件层写),跳过不算
    { id: "\u601D\u6F6E", name: "\u5404\u8BF4\u7684\u63A5\u53D7\u5EA6(0\u20131)", unit: "region", every: step2, cols: names2, min: 0, max: 1, off: 0, after: ["\u5408"], zeroStays: true, rule: ideoRule },
    { id: "\u56FD\u4E2D", name: "\u5404\u56FD\u5404\u8BF4\u7684\u63A5\u53D7\u5EA6(\u6309\u4EBA\u53E3\u52A0\u6743)", unit: "polity", every: step2, cols: names2, min: 0, max: 1, off: 0, after: ["\u601D\u6F6E"], rule: polityRule }
  ];
  return [...inputs, ...tables2.map((c) => ({ ...c, consts, builtin: true }))];
}

